from pathlib import Path
from html import escape
ROOT=Path(__file__).parent
ORIGIN='https://cmcnosky.github.io/blue-star-spray-foam-preview/'
SOCIAL_META='<meta property="og:image" content="https://cmcnosky.github.io/blue-star-spray-foam-preview/assets/blue-star-link-preview-v4.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:type" content="image/png"><meta property="og:image:alt" content="Blue Star Spray Foam: Comfort starts inside. Residential and commercial insulation with an illustrated insulated building section."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="https://cmcnosky.github.io/blue-star-spray-foam-preview/assets/blue-star-link-preview-v4.png"><meta name="twitter:image:alt" content="Blue Star Spray Foam: Comfort starts inside. Residential and commercial insulation with an illustrated insulated building section.">'
BACKEND='https://blue-star-spray-foam-rebuild.cmcnosky.chatgpt.site'
RAY='M32 3 39 20.876 35.2 26.5 28.8 26.5 25 20.876Z'
mark='<svg class="brand-mark" viewBox="0 0 64 64" aria-hidden="true">'+''.join(f'<path class="ray ray-{i}" d="{RAY}" transform="rotate({i*72} 32 33)"/>' for i in range(5))+'</svg>'
logo=f'<a class="brand" href="./" aria-label="Blue Star Spray Foam Insulation home">{mark}<span class="brand-words"><strong>BLUE STAR</strong><span>SPRAY FOAM<br>INSULATION</span></span></a>'
arrow='<span aria-hidden="true">↗</span>'
def button(text='Start your project',href='project.html',style='primary'):
 return f'<a class="button {style}" href="{href}">{text} {arrow}</a>'
def head(title,description,path=''):
 return f'''<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">{('<base href="'+ORIGIN+'">') if path=='404.html' else ''}<meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#142d3b"><title>{escape(title)} | Blue Star Spray Foam Insulation</title><meta name="description" content="{escape(description)}"><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="base.css"><link rel="stylesheet" href="styles.css"><link rel="canonical" href="{ORIGIN+path}"><meta property="og:title" content="{escape(title)} | Blue Star"><meta property="og:description" content="{escape(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN+path}">{SOCIAL_META}<script>try{{if((localStorage.getItem('bs-main-theme')||localStorage.getItem('bs-concept-theme')||localStorage.getItem('bs-preview-theme'))==='light')document.documentElement.dataset.theme='light'}}catch(e){{}}</script><script src="site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'''
def header(active=''):
 project_href='#project-form-start' if active=='project.html' else 'project.html'
 project_label='Back to project form' if active=='project.html' else 'Start your project'
 nav=[('Residential','residential.html'),('Commercial','commercial.html'),('How it works','./#process')]
 links=''.join(f'<a href="{u}"'+(' aria-current="page"' if active==u else '')+f'>{t}</a>' for t,u in nav)
 return f'''<header class="site-header"><div class="wrap nav-row">{logo}<nav id="main-nav" aria-label="Main navigation">{links}<a class="mobile-project" href="{project_href}">{project_label} ↗</a></nav>{button(project_label,project_href)}<button class="theme-toggle" aria-label="Use light colors" title="Change color theme"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg></button><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Open navigation"><span></span><span></span></button></div></header>'''
def footer(active=''):
 project_href='#project-form-start' if active=='project.html' else 'project.html'
 project_label='Back to form' if active=='project.html' else 'Start your project'
 return f'''<footer class="site-footer"><div class="wrap footer-top"><div>{logo}<p>Show us the building.<br>Let’s work out the next step.</p></div><div><span class="eyebrow">TALK TO JOSH</span><a class="footer-phone" href="tel:+18643734464">(864) 373-4464</a><a href="mailto:Joshua@bluestarsprayfoam.com">Joshua@bluestarsprayfoam.com</a></div><div><span class="eyebrow">EXPLORE</span><a href="residential.html">Residential projects</a><a href="commercial.html">Commercial & builders</a><a href="residential.html#air-sealing">Air sealing & encapsulation</a><a href="{project_href}">Send plans or project details</a><a href="privacy.html">Privacy & uploads</a></div></div><div class="wrap footer-bottom"><span>Blue Star Spray Foam Insulation · Greer, SC</span><span>SC · NC · GA · TN — project coverage confirmed individually.</span><a href="#top">Back to top ↑</a></div></footer><div class="mobile-dock"><a href="tel:+18643734464">Call Josh</a><a href="{project_href}">{project_label} ↗</a></div></body></html>'''
def cta():
 return f'''<section class="closing wrap"><div><p class="eyebrow">A GOOD PLACE TO START</p><h2>Bring the project.<br><span>We’ll bring the guidance.</span></h2></div><div><p>Plans, photos, a rough surface area, or simply a description. You do not need to choose a foam product.</p>{button('Send your project')}</div></section>'''
def faqs(items):
 return '<div class="faq-list">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div><p>{a}</p></div></details>' for q,a in items)+'</div>'
faq_items=[
('Do I need to choose open-cell or closed-cell foam?','No. Share your building and your goal. Josh considers the assembly, available depth, moisture conditions and any project requirements before recommending an approach.'),
('What if I don’t have drawings or measurements?','Start with a short description and your project location. Photos can help, but you can begin without them. Josh will explain what information is useful next.'),
('Will I receive an instant price?','No. Plans begin the review. Josh checks the scope and missing details before discussing a useful estimate, arranging a site visit or preparing a written proposal. Uploading files does not reserve a date.'),
('Which square footage should I send?','If you know it, send the combined area of the surfaces you want insulated—such as walls and a roof deck or ceiling. Building floor area is different. If your number is floor area, label it that way; if you are unsure, leave the area blank.'),
('Where does Blue Star work?','Blue Star is based in Greer, South Carolina. Its published service area includes South Carolina, North Carolina, Georgia and Tennessee. Send the project location so travel, coverage and availability can be confirmed.')]
hero=f'''<section class="opening"><div class="opening-grid wrap"><div class="opening-copy"><p class="eyebrow">SPRAY FOAM INSULATION · GREER, SC</p><h1>Insulation for<br>the way <span>you build.</span></h1><p class="opening-lead">A home. A renovation. A commercial project. <br>Start with the building. Josh will help work out the insulation.</p><div class="actions">{button('Show us your project')}<a class="text-link" href="tel:+18643734464">Talk to Josh ↗</a></div><p class="opening-note">Plans, photos or a few words are enough to begin.</p></div><figure class="opening-photo"><img src="assets/application.jpg" alt="Spray foam application inside a timber-framed building" width="1024" height="768" fetchpriority="high"><figcaption><span>THE WORK, UP CLOSE</span><span>From the Blue Star gallery</span></figcaption></figure></div><div class="opening-bottom wrap"><span>BASED IN GREER, SC.</span><p>South Carolina · North Carolina · Georgia · Tennessee<br><b>Project coverage and availability confirmed individually.</b></p><a href="#process" aria-label="See how project review works">Explore the process <span aria-hidden="true">↓</span></a></div></section>'''
applications=f'''<section class="project-paths" id="applications"><div class="wrap"><div class="editorial-heading"><div><p class="eyebrow">01 / FIND YOUR STARTING POINT</p><h2>Different buildings.<br>The same thoughtful start.</h2></div><p>Choose the path that fits your project.<br>You can send what you already have.</p></div><div class="project-pair"><a class="project-story commercial-story" href="commercial.html"><div class="story-photo"><img src="assets/metal-building.jpg" alt="Insulated roof and wall surfaces inside a metal-framed building" width="1200" height="1600" loading="lazy"><span>COMMERCIAL</span></div><div class="story-caption"><div><h3>For the project team.</h3><p>Drawings, specifications, scope and bid deadlines.</p></div><span class="round-arrow" aria-hidden="true">↗</span></div></a><a class="project-story" href="residential.html"><div class="story-photo"><img src="assets/residential.jpg" alt="Spray foam installed between wood framing" width="1152" height="864" loading="lazy"><span>RESIDENTIAL</span></div><div class="story-caption"><div><h3>For the place you call home.</h3><p>New construction, renovations and existing spaces.</p></div><span class="round-arrow" aria-hidden="true">↗</span></div></a></div><div class="secondary-story"><img src="assets/crawlspace.jpg" alt="Insulation application along a crawlspace wall" width="500" height="375" loading="lazy"><div><p class="eyebrow">AIR SEALING & ENCAPSULATION</p><h3>Drafts or crawlspace concerns?</h3><p>Show Josh the crawlspace, drafts or moisture concerns you want to discuss.</p></div><a class="text-link" href="residential.html#air-sealing">Explore these services ↗</a></div><p class="gallery-provenance">Every building is different. Share your plans or photos so Josh can review your project.</p></div></section>'''
process=f'''<section class="review-process wrap" id="process" tabindex="-1"><div class="process-heading"><p class="eyebrow">02 / A CLEAR NEXT STEP</p><h2>You show us the project.<br>We help make sense of it.</h2><p>You don’t have to arrive with an insulation specification. Start with the information you have.</p>{button('Send plans or project details')}</div><ol class="process-rows"><li><span>01</span><div><h3>Send what you have.</h3><p>Plans, photos, a rough surface area or a short description. Include the location and how to reach you.</p></div></li><li><span>02</span><div><h3>Josh reviews the details.</h3><p>The likely insulation surfaces, project requirements and information needed to move forward.</p></div></li><li><span>03</span><div><h3>Agree on the next step.</h3><p>Clarify the scope, discuss an estimate, arrange a site visit or work toward a written proposal.</p></div></li></ol></section>'''
surface='''<section class="surface-section wrap"><div class="surface-drawing"><svg viewBox="0 0 460 320" role="img" aria-labelledby="surface-title"><title id="surface-title">Walls and roof surface area are different from the floor footprint</title><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="currentColor" stroke-width=".4" opacity=".18"/></pattern></defs><rect width="460" height="320" fill="url(#grid)"/><path d="M68 150 240 76 394 139 230 214Z" fill="#8ec3cc" opacity=".12"/><path d="M68 150v100l162 53V214Z" fill="#87c4db" opacity=".5"/><path d="M230 214v89l164-69v-95Z" fill="#87c4db" opacity=".25"/><path d="M68 150 156 38 240 76 230 214Z" fill="#b4da8b" opacity=".35"/><path d="M156 38 318 89 394 139 230 214Z" fill="#b4da8b" opacity=".7"/><g fill="none" stroke="currentColor" stroke-width="2"><path d="M68 150v100l162 53 164-69v-95L318 89 156 38Z"/><path d="M68 150 230 214 394 139M156 38 230 214v89"/><path stroke-dasharray="5 5" opacity=".6" d="M68 250 236 178 394 234"/></g><path d="M267 96h101" stroke="#ffad72" stroke-width="2"/><circle cx="267" cy="96" r="4" fill="#ffad72"/><text x="316" y="79" fill="currentColor" font-size="13" font-weight="700">ROOF DECK</text><path d="M112 211H29" stroke="#ffad72" stroke-width="2"/><circle cx="112" cy="211" r="4" fill="#ffad72"/><text x="20" y="192" fill="currentColor" font-size="13" font-weight="700">WALLS</text></svg><span>ILLUSTRATION · NOT A PROJECT TAKEOFF</span></div><div><p class="eyebrow">03 / AN IMPORTANT DISTINCTION</p><h2>Think walls.<br>Think roof surfaces.</h2><p>Foam is applied to surfaces. A 2,000 sq ft building can have a very different amount of wall and roof area to insulate.</p><p>If you know the area of the surfaces, share it. If you only know the floor area, say so. If you’re unsure, send the plans or leave the number blank.</p><a class="text-link" href="project.html">Let Josh review what you have ↗</a></div></section>'''

commercial_teaser=f'''<section class="bid-band"><div class="wrap bid-grid"><div><p class="eyebrow">FOR BUILDERS, OWNERS & PROJECT TEAMS</p><h2>A serious project<br>deserves a clear scope.</h2><p>Send your current package. Josh can review what Blue Star is being asked to price and the questions that need answering first.</p>{button('Commercial project guide','commercial.html','ink')}</div><div class="bid-list"><p>YOUR PACKAGE IS THE START</p><div><span>01</span><strong>Drawings & specifications</strong></div><div><span>02</span><strong>Requested scope & addenda</strong></div><div><span>03</span><strong>Project location & bid deadline</strong></div><small>Have a deadline? Call Josh to confirm availability.</small></div></div></section>'''
main=hero+applications+process+'<div class="surface-band">'+surface+'</div>'+commercial_teaser+f'<section class="section wrap faq-section"><div><p class="eyebrow">BEFORE YOU SEND</p><h2>A few good questions.</h2><p>Clear answers to help you get started.</p><a class="text-link" href="tel:+18643734464">Call (864) 373-4464 ↗</a></div>'+faqs(faq_items)+'</section>'+cta()
ROOT.joinpath('index.html').write_text(head('Insulation for the way you build.','Spray foam insulation for homes and commercial projects. Share your plans, photos or project details with Josh.')+header()+f'<main id="main" tabindex="-1"><div id="top" tabindex="-1"></div>{main}</main>'+footer())

def page(title,description,path,content):
 ROOT.joinpath(path).write_text(head(title,description,path)+header(path)+'<main id="main" tabindex="-1"><div id="top" tabindex="-1"></div>'+content+'</main>'+footer(path))
def intro(label,title,body):
 return f'<section class="page-intro wrap"><a class="back-link" href="./">← Home</a><p class="eyebrow">{label}</p><h1>{title}</h1><p>{body}</p></section>'
commercial=intro('COMMERCIAL · BUILDERS · PROJECT TEAMS','Make the scope clearer.<br><span>Move the project forward.</span>','Send the current plans and project requirements. Josh reviews what Blue Star is being asked to price, identifies missing information and confirms whether Blue Star can respond by your bid deadline.')+f'''<section class="wrap commercial-summary"><div class="summary-actions">{button('Send a bid package')}<p>Time-sensitive? <a href="tel:+18643734464">Call (864) 373-4464</a> to confirm availability.</p></div><div class="scope-pair"><article><p class="eyebrow">WHAT TO SEND</p><h2>Your current package.</h2><ul><li>Project name, location and bid due date</li><li>Current drawings and specifications</li><li>Issued addenda and requested scope</li><li>Bid form, alternates or qualification requirements, if applicable</li></ul><p>PDF, JPG or PNG · up to 5 files, 20 MB each. A shared-file link is also an option.</p></article><article><p class="eyebrow">WHAT THE REVIEW IS FOR</p><h2>A useful next decision.</h2><ul><li>Which surfaces and assemblies need review</li><li>What is specified and what still needs clarification</li><li>What information is needed for pricing</li><li>Whether to proceed to a site visit or written proposal</li></ul><p>Josh makes the recommendations. Project approval requirements still apply to any proposed change.</p></article></div></section><section class="commercial-photo wrap"><img src="assets/metal-building.jpg" alt="Insulated walls and roof deck in a metal-framed interior" loading="lazy"><div><p class="eyebrow">SCOPE BEFORE ASSUMPTIONS</p><h2>Price the surfaces.<br>Understand the conditions.</h2><p>Surface area, specified system and thickness, access, substrate, preparation and protective coatings can all affect a proposal. A footprint alone is not a complete takeoff.</p></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">BEFORE A PROPOSAL BECOMES A COMMITMENT</p><h2>Put the important details in writing.</h2></div><p>Use the review to clarify the work before schedule and pricing are agreed.</p></div><div class="detail-grid"><article><span>01 / SCOPE</span><h3>Assemblies & quantities</h3><p>Confirm the surfaces, document revision, area basis, specified product and thickness, and any exclusions.</p></article><article><span>02 / EXECUTION</span><h3>Site conditions & access</h3><p>Clarify substrate readiness, working heights, sequencing, other trades and the installation window.</p></article><article><span>03 / DOCUMENTATION</span><h3>Your procurement requirements</h3><p>Send insurance, qualification, product-submittal or closeout requirements. Josh confirms what Blue Star can provide.</p></article></div></section>'''+f'<section class="section wrap faq-section"><div><p class="eyebrow">COMMERCIAL QUICK ANSWERS</p><h2>Before you send.</h2></div>'+faqs([
('Can I send a bid invitation or scope sheet?','Yes. Include it with the current drawings and any specifications or addenda. Put the due date and contact person in the description. Sending a package does not by itself confirm bid participation.'),
('Can Blue Star suggest a different insulation approach?','Josh can identify questions or possible alternatives. Any change to a specified system must go through the project’s required design and approval process.'),
('Can I get an immediate budget from the website?','The website does not issue an automatic price. Josh reviews the information first so a discussion about budget is tied to a defined scope and visible assumptions.'),
('Do I need a complete drawing package to begin?','No. A description, photos or rough surface area can start an early discussion. The information needed for a formal bid will be confirmed separately.')])+'</section>'+cta()
page('Commercial project review','A clear path for plans, specifications, addenda and bid requirements. Josh reviews the scope before pricing.','commercial.html',commercial)
residential=intro('HOMES · RENOVATIONS · NEW CONSTRUCTION','Start with the space.<br><span>Not a foam decision.</span>','A hot room, a new addition, an unfinished attic or a building from the ground up. Tell Josh what you want to improve, and he’ll help work out the insulation questions.')+f'''<section class="residential-lead wrap"><img src="assets/residential.jpg" alt="Spray foam installed between wood wall and roof framing" width="1152" height="864"><div><p class="eyebrow">YOU DON’T NEED ALL THE ANSWERS</p><h2>A few photos can<br>start the conversation.</h2><p>Send an overview of the space and, if possible, a closer view of the framing or existing insulation. Add your city or ZIP and what you’re trying to accomplish.</p>{button('Show Josh your project')}<p class="small-note">No photos? A description is enough to begin.</p></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">WHAT YOU’RE WORKING ON</p><h2>The building guides the approach.</h2></div></div><div class="detail-grid"><article><span>NEW CONSTRUCTION</span><h3>Plan while it’s accessible.</h3><p>Share the plans, framing stage and any issued insulation requirements. Josh can review the intended surfaces and installation timing.</p></article><article><span>RENOVATION & EXISTING SPACES</span><h3>Show what’s there.</h3><p>Photos, access conditions and a short description of the concern help start a useful discussion. A site visit may be needed.</p></article><article id="crawlspaces"><span>CRAWLSPACES & ENCAPSULATION</span><h3>Look beyond the insulation.</h3><p>Water entry, drainage, existing materials and ventilation or conditioning all matter. Describe known moisture issues so they can be considered.</p></article></div></section><section class="wrap service-note" id="air-sealing" tabindex="-1"><div><p class="eyebrow">DRAFTS & CRAWLSPACE CONCERNS</p><h2>Air sealing &amp; encapsulation.</h2></div><div><p>Describe the drafts, crawlspace conditions or moisture concerns you want addressed. Josh can review the appropriate scope; insulation, air sealing and moisture management are related decisions with different requirements.</p><a class="text-link" href="project.html">Discuss the space with Josh ↗</a></div></section>'''+surface+f'<section class="section wrap faq-section"><div><p class="eyebrow">BEFORE YOU DECIDE</p><h2>Understand what<br>you’re agreeing to.</h2><p>A useful proposal should explain the surfaces, products, thickness or performance basis, preparation, price and important exclusions.</p></div>'+faqs(faq_items[:4])+'</section>'+cta()
page('Residential insulation','Show Josh your home, addition, attic or new construction. Start with photos, plans or a description.','residential.html',residential)
project=intro('PROJECT REVIEW','Show us what<br><span>you’re working on.</span>','Plans, photos, a rough surface area or a few words. Any one is enough to start. Josh will advise on the insulation.')+f'''<section class="wrap intake-layout"><div class="intake-main" id="project-form-start" tabindex="-1"><div class="intake-status"><span class="status-dot"></span><p>Send your project details for Josh’s review.</p></div><div id="intake-loading" role="status">Loading the project form…</div><iframe id="project-intake" title="Send plans and project details to Blue Star" src="{BACKEND}/intake-embed" referrerpolicy="strict-origin-when-cross-origin" allow="clipboard-write" loading="eager"></iframe><div class="form-fallback"><strong>Having trouble with the form?</strong><a href="{BACKEND}/estimate" target="_blank" rel="noopener">Open the form in a new tab ↗</a><span>Or call Josh at (864) 373-4464.</span></div><noscript><p>JavaScript helps this form fit the page. <a href="{BACKEND}/estimate">Open the form directly</a>, or call (864) 373-4464.</p></noscript></div><aside class="intake-aside"><p class="eyebrow">WHAT HAPPENS NEXT</p><h2>You bring the project.<br>Josh brings the guidance.</h2><ol><li><b>Review the information.</b><span>Plans, surfaces, existing conditions and any project requirements.</span></li><li><b>Clarify what matters.</b><span>Likely insulation areas, important assumptions and missing details.</span></li><li><b>Agree on the next step.</b><span>A scope discussion, estimate, site visit or written proposal.</span></li></ol><div class="aside-call"><span>Have a deadline?</span><a href="tel:+18643734464">(864) 373-4464 ↗</a><p>Call to confirm availability. An upload does not reserve a date.</p></div></aside></section>'''
page('Start your project','Send plans, photos or a description to Blue Star. No technical product selections are required.','project.html',project)
privacy=intro('PRIVACY & PROJECT FILES','Know where<br><span>your information goes.</span>','How this website handles your project information, files and review request.')+f'''<section class="wrap prose"><h2>Project submissions</h2><p>The embedded form sends your contact details, project information and selected files to Blue Star’s project submission service. GitHub Pages serves the website pages; project files are stored by the separate submission service.</p><p>The review workflow may process project details and files through ChatGPT/OpenAI to prepare a preliminary Blue Star brief for Josh. A private Blue Star brief may be emailed to Josh. Josh checks the information and makes the final recommendations. Delivery is not guaranteed; call about urgent deadlines.</p><p>Only submit material you are authorized to share. Avoid unnecessary personal information, passwords or access codes. The form explains its current review consent before you send.</p><h2>Josh’s review</h2><p>Josh reviews the project and makes the final decisions about the recommended approach, scope, quantities, materials, price and schedule. An upload is not a firm quote, booking or construction instruction.</p><h2>Privacy details and requests</h2><p>Read the <a href="{BACKEND}/privacy" target="_blank" rel="noopener">intake service’s privacy and file information</a> for the full current handling details. For questions about a submission, contact <a href="mailto:Joshua@bluestarsprayfoam.com">Joshua@bluestarsprayfoam.com</a> or <a href="tel:+18643734464">(864) 373-4464</a>.</p><h2>This website</h2><p>The website stores only your light/dark color preference in your browser. It does not add a marketing analytics or advertising tracker. GitHub and the intake host may process technical information needed to provide their services.</p><p><a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection" target="_blank" rel="noopener">GitHub Pages data collection information ↗</a></p></section>'''
page('Privacy and uploads','How the website and Blue Star project submission service handle your information.','privacy.html',privacy)
page('Page not found','Find your way back to Blue Star Spray Foam.','404.html',intro('PAGE NOT FOUND','Let’s get you<br><span>back on track.</span>','The page may have moved. Start from the home page or send Josh your project.')+'<section class="wrap error-actions">'+button('Go to the home page','./')+button('Start your project','project.html','outline')+'</section>')
