ROOT.joinpath('robots.txt').write_text('User-agent: *\nDisallow: /\n')
print('Generated 6 static pages.')

# Previously shared concept links resolve to the current main version.
for filename in ['index.html','residential.html','commercial.html','project.html','privacy.html','404.html']:
 target='../'+('' if filename=='index.html' else filename)
 canonical=ORIGIN+('' if filename=='index.html' else filename)
 (ROOT/'concept'/filename).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta http-equiv="refresh" content="0;url={target}"><link rel="canonical" href="{canonical}"><title>Blue Star Spray Foam Insulation</title>{SOCIAL_META}<script>location.replace({repr(target)}+location.search+location.hash)</script></head><body><p>This design is now the main website. <a href="{target}">Continue to Blue Star Spray Foam Insulation</a>.</p></body></html>')
